package com.ruoyi.metal.service;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;import java.math.BigDecimal;import org.springframework.jdbc.core.JdbcTemplate;import com.ruoyi.metal.security.FactoryScope;import com.ruoyi.metal.catalog.WarehouseRequests.Line;import com.ruoyi.common.exception.ServiceException;
class ReleasedImportAllowanceTest {
 private List<Map<String,Object>> preview(List<Line> lines){var jdbc=mock(JdbcTemplate.class);when(jdbc.queryForList(anyString(),any(Object[].class))).thenAnswer(a->{String q=a.getArgument(0);if(q.contains("metal_warehouse WHERE"))return List.of(Map.of("factory_id",1L,"status","0"));if(q.startsWith("SELECT factory_id,status FROM metal_work_order"))return List.of(Map.of("factory_id",1L,"status","IN_PROGRESS"));if(q.startsWith("SELECT s.sequence_no"))return List.of(Map.of("sequence_no",2L,"product_id",3L,"work_order_id",10L));if(q.contains("metal_inventory WHERE"))return List.of(Map.of("factory_id",1L,"warehouse_id",2L,"category","SEMI","reference_id",3L,"batch_no","B","net_weight",new BigDecimal("100"),"quantity",10L,"code","P","name","半成品"));return List.of();});try(var mocks=mockConstruction(SemiFlowService.class,(m,c)->{when(m.sourceBatch(anyMap())).thenReturn(Map.of("sequence_no",1L,"work_order_id",20L,"item_id",22L));when(m.entryCapacity(anyLong(),anyLong())).thenReturn(20L);when(m.availableRelease(anyLong())).thenReturn(new HashMap<>(Map.of("available_quantity",4L,"available_weight",new BigDecimal("40.000000"))));})){var result=new WarehouseImportService(jdbc,mock(FactoryScope.class)).preview(new WarehouseImportService.Input(1L,2L,"PRODUCTION_OUT",10L,11L,12L,lines,Map.of()));verify(jdbc,never()).update(anyString(),any(Object[].class));return result;}}
 private Line line(long release,long q,String w){return new Line(5L,null,"SEMI",3L,null,new BigDecimal(w),q,null,null,null,null,null,null,null,release);}
 @Test void rejectsAllPiecesWithoutAllWeight(){var e=assertThrows(ServiceException.class,()->preview(List.of(line(7,4,"39"))));assertTrue(e.getMessage().contains("7"));assertTrue(e.getMessage().contains("2"));}
 @Test void rejectsAllWeightWithoutAllPieces(){assertThrows(ServiceException.class,()->preview(List.of(line(7,3,"40"))));}
 @Test void acceptsFullAndPartialTransfers(){assertEquals(1,preview(List.of(line(7,4,"40"))).size());assertEquals(1,preview(List.of(line(7,2,"19"))).size());}
 @Test void sumsSamePoolBeforeChecking(){assertThrows(ServiceException.class,()->preview(List.of(line(7,2,"20"),line(7,2,"19"))));assertEquals(2,preview(List.of(line(7,1,"5"),line(7,3,"35"))).size());}
 @Test void differentPoolsDoNotShareReleaseAllowance(){assertEquals(2,preview(List.of(line(7,2,"19"),line(8,2,"19"))).size());assertThrows(ServiceException.class,()->preview(List.of(line(7,4,"39"),line(8,1,"1"))));}
 @Test void sixDecimalResidualIsRejected(){assertThrows(ServiceException.class,()->preview(List.of(line(7,4,"39.999999"))));assertEquals(2,preview(List.of(line(7,2,"10.000001"),line(7,2,"29.999999"))).size());}
}
